#!/usr/bin/env python3
"""Generate the small integration inventory from the lock/manifest; not a binary SBOM."""
import argparse
import hashlib
import json
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent.parent


def render():
    lock = json.loads((ROOT / "providers.lock.json").read_text(encoding="utf-8"))
    manifest = yaml.safe_load((ROOT / "third_party/manifest.yaml").read_text(encoding="utf-8"))
    for dependency in manifest["incorporated_code"]:
        for relative, expected in dependency["files"].items():
            path = ROOT / relative
            if (path.is_symlink() or not path.is_file() or not path.resolve().is_relative_to(ROOT.resolve())
                    or hashlib.sha256(path.read_bytes()).hexdigest() != expected):
                raise ValueError("incorporated dependency checksum mismatch: " + relative)
    result = dict(schema="framework-memory/integration-inventory/v1", scope="direct-integration-not-transitive-SBOM",
                  providers={k: v for k, v in lock.items() if k != "schema"},
                  python_runtime=manifest["python_runtime"],
                  external_dependencies=manifest["external_dependencies"],
                  reviewed_not_copied=manifest["reviewed_not_copied"],
                  incorporated_code=manifest["incorporated_code"], host_requirements=manifest["host_requirements"])
    return json.dumps(result, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def constraints():
    manifest = yaml.safe_load((ROOT / "third_party/manifest.yaml").read_text(encoding="utf-8"))
    rows = manifest["python_runtime"]["dependencies"]
    if len({r["name"].lower().replace("_", "-") for r in rows}) != len(rows):
        raise ValueError("duplicate runtime dependency")
    lines = ["# Generated by third_party/inventory.py from third_party/manifest.yaml.",
             "# Version constraints, not a hash-locked binary distribution. No optional extras."]
    for row in sorted(rows, key=lambda r: r["name"].lower()):
        lines.append(row["name"] + "==" + str(row["version"]) +
                     ("; " + row["marker"] if row.get("marker") else ""))
    return "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    changed = False
    for relative, content in (("third_party/inventory.json", render()), ("constraints.txt", constraints())):
        target = ROOT / relative
        stale = not target.exists() or target.read_text(encoding="utf-8") != content
        changed |= stale
        if args.check:
            print(relative + (" out of date" if stale else " current"))
        else:
            target.write_text(content, encoding="utf-8", newline="\n")
            print(relative + " generated")
    return int(args.check and changed)


if __name__ == "__main__":
    raise SystemExit(main())
